import {uiQuery,uiQueryAll} from './router.js';
import {absenceOverview,weekdayDates} from './panel-core.js';
import {calendarLayout,clockLabel,HOUR_HEIGHT} from './calendar-core.js';
import {addDays,weekMonday,weekDays,weekSessions} from './weekly-core.js';
import {FORMAT,STATUSES,keyOf,validDate,totals,parseImport,mergeRecords} from './attendance-core.js';
const $=s=>uiQuery(s), safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={attended:'Katıldım',half:'Yarım',absent:'Katılmadım',unknown:'Bilinmiyor'};
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const sessionFeedback=new Map();
let courses=[],records=[],undo=null,selected='',preview=null,storageError=false,migration=null,revision=0,metadata={},sourceCandidate=null,busy=false,schoolCourses=[],schoolAnnouncements=[],weekStart=weekMonday(today);
async function read(){const response=await fetch('/api/attendance',{cache:'no-store'});const saved=await response.json();if(!response.ok)throw Error(saved.error||'Yerel kayıt okunamadı');records=parseImport(saved,saved.courses.map(c=>c.id),today);courses=saved.courses;metadata=saved;revision=saved.revision;migration=saved.migrationId||null;const first=weekMonday(metadata.semester.start),last=weekMonday(metadata.semester.end);weekStart=weekStart<first?first:weekStart>last?last:weekStart;}
async function write(next,message,{importedAt=migration}={}){
 if(busy)return false;busy=true;uiQueryAll('#attendanceApp button, #weekApp button').forEach(b=>b.disabled=true);
 const before={records:records.map(r=>({...r})),migration};
 try{const response=await fetch('/api/attendance',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({records:next,revision,migrationId:importedAt})});const result=await response.json();if(!response.ok)throw Error(result.error||'Yerel dosyaya kaydedilemedi');records=result.records;metadata.updatedAt=result.updatedAt||metadata.updatedAt;revision=result.revision;migration=result.migrationId;undo=before;storageError=false;renderSummary();renderRows();renderWeek();$('#attendanceMessage').textContent=message+' · Yerel dosyaya kaydedildi.';$('#weekMessage').textContent=message+' · Yerel dosyaya kaydedildi.';return true;}catch(e){$('#attendanceMessage').textContent=e.message+' Değişiklik kaydedilmiş sayılmamalı; yenileyerek kontrol et.';$('#weekMessage').textContent=$('#attendanceMessage').textContent;return false;}finally{busy=false;uiQueryAll('#attendanceApp button, #weekApp button').forEach(b=>b.disabled=false);$('#attendanceUndo').disabled=!undo;$('#attendanceApply').disabled=!preview;syncWeekButtons();}
}
function chosen(){return records.filter(r=>r.courseId===selected);}
function renderSummary(){const t=totals(chosen()),c=courses.find(c=>c.id===selected);$('#attendanceTotals').innerHTML=Object.entries(t).map(([status,n])=>`<div class="attendance-total ${status}"><strong>${n}</strong><span>${names[status]}</span></div>`).join('');$('#attendanceCount').textContent=chosen().length+' kayıtlı gün';$('#attendanceCourseName').textContent=c?.name||selected;const used=t.absent+t.half*.5,number=n=>n.toLocaleString('tr-TR');$('#attendanceLimit').textContent=c?.userAbsenceLimit!=null?`Kişisel ayarın: ${number(c.userAbsenceLimit)} oturum · Kullanılan: ${number(used)} · Kalan: ${number(c.userAbsenceLimit-used)}. Resmî/üniversite onaylı limit değildir. Yarım kayıt 0,5 sayılır.`:'Devamsızlık limiti bilinmiyor.';$('#migrationStatus').textContent='Kişisel kayıtların yalnız bu bilgisayarda saklanır. Boş günler devamsızlık sayılmaz.';$('#attendanceMigrate').hidden=true;}
function renderRows(){const list=chosen().sort((a,b)=>b.date.localeCompare(a.date));$('#attendanceRows').innerHTML=list.length?list.map(r=>`<div class="attendance-row"><span>${safe(new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'}).format(new Date(r.date+'T12:00:00+03:00')))}</span><span class="attendance-status ${r.status}">${names[r.status]}</span><div><button type="button" class="text-button" data-edit="${safe(r.date)}" aria-label="${safe(r.date)} kaydını düzenle">Düzenle</button><button type="button" class="text-button muted" data-remove="${safe(r.date)}" aria-label="${safe(r.date)} kaydını kaldır">Kaldır</button></div></div>`).join(''):'<div class="attendance-empty">Bu ders için kayıt yok. Tarih seçerek başlayabilirsin.<small>Kaydedilmeyen günler bilinmeyendir; katılmadım sayısına eklenmez.</small></div>';}
function selectCourse(id){if(!courses.some(c=>c.id===id))return;selected=id;$('#attendanceCourse').value=id;$('#attendanceDate').value=today;$('#attendanceStatus').value='unknown';renderSummary();renderRows();$('#attendanceMessage').textContent='';}
function build(){
 selected=courses[0]?.id||"";
 $('#attendanceApp').innerHTML=`<div class="attendance-heading"><div><h3 id="attendanceCourseName"></h3><span class="muted" id="attendanceCount"></span></div><button class="button outline" type="button" id="attendanceUndo" disabled>Son işlemi geri al</button></div><div id="attendanceTotals" class="attendance-totals"></div><p class="attendance-explanation" id="attendanceLimit"></p><button type="button" class="button outline" id="attendanceMigrate">Doğrulanmış eski kayıtları önizle</button><p class="attendance-explanation">Toplamlar yalnızca eklediğin tarihleri kapsar. “Bilinmiyor” ve hiç kaydedilmemiş günler devamsız sayılmaz; boş tarihler devamsızlığa dönüştürülmez.</p><form id="attendanceForm" class="attendance-form"><label>Ders<select id="attendanceCourse">${courses.map(c=>`<option value="${safe(c.id)}">${safe(c.id)}</option>`).join('')}</select></label><label>Tarih<input id="attendanceDate" type="date" max="${today}" value="${today}" required></label><label>Durum<select id="attendanceStatus"><option value="unknown">Bilinmiyor</option><option value="attended">Katıldım</option><option value="half">Yarım</option><option value="absent">Katılmadım</option></select></label><button class="button primary" type="submit">Kaydı kaydet</button></form><p id="attendanceMessage" class="attendance-message" role="status" aria-live="polite">${storageError?'Kayıtlı veri okunamadı. Mevcut depolama üzerine yazmadan önce bir yedek kontrol et.':''}</p><div id="attendanceRows"></div><details class="attendance-transfer"><summary>Yedekle / geçmiş kayıtları içe aktar</summary><p>JSON yedeğini dışa aktarabilir veya aşağıya yapıştırabilirsin. Aktarım önce önizlenir; aynı ders/tarih çakışmaları açıkça gösterilir. Yoklama bu bilgisayardaki özel dizine kaydedilir. Bu işlem kişisel tamamlandı işaretlerini değiştirmez. </p><button type="button" class="button outline" id="attendanceExport">JSON yedeğini indir ↧</button><label for="attendanceImport">Yoklama JSON’u</label><textarea id="attendanceImport" rows="6" spellcheck="false" placeholder='{"format":"kepler-attendance","version":1,"records":[]}'></textarea><small>Her kayıt: <code>{"courseId":"DEMO101","date":"YYYY-MM-DD","status":"attended | half | absent | unknown"}</code>. Ders + tarih başına tek kayıt.</small><div class="import-actions"><button type="button" class="button outline" id="attendancePreview">Aktarımı önizle</button><label>Çakışan tarihler<select id="attendanceMerge"><option value="keep">Mevcut kayıtları koru</option><option value="replace">Önizlenen kayıtlarla değiştir</option></select></label></div><div id="attendanceImportPreview" role="status"></div><button type="button" class="button primary" id="attendanceApply" disabled>Önizlenen aktarımı uygula</button></details>`;
 $('#attendanceCourse').value=selected;
 $('#attendanceCourse').addEventListener('change',e=>selectCourse(e.target.value));
 $('#attendanceForm').addEventListener('submit',async e=>{e.preventDefault();const date=$('#attendanceDate').value,status=$('#attendanceStatus').value;if(!validDate(date)||date>today||!STATUSES.includes(status))return;const r={courseId:selected,date,status};if(storageError){$('#attendanceMessage').textContent='Eski tarayıcı verisi okunamadığı için üzerine yazılmadı. Önce mevcut veriyi kurtarmak gerekiyor.';return;}write(mergeRecords(records,[r],true),'Kişisel yoklama kaydedildi. Aynı tarihin önceki durumu varsa güncellendi.');});
 $('#attendanceRows').addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),remove=e.target.closest('[data-remove]');if(edit){const r=records.find(r=>r.courseId===selected&&r.date===edit.dataset.edit);$('#attendanceDate').value=r.date;$('#attendanceStatus').value=r.status;$('#attendanceDate').focus();$('#attendanceMessage').textContent='Kaydı düzenliyorsun. Yeni durumunu seçip kaydet.';}if(remove)write(records.filter(r=>!(r.courseId===selected&&r.date===remove.dataset.remove)),'Kayıt kaldırıldı. Son işlemi geri alabilirsin.');});
 $('#attendanceUndo').addEventListener('click',undoLast);
 $('#attendanceExport').addEventListener('click',()=>{if(storageError){$('#attendanceMessage').textContent='Depolama okunamadı; eksik yedek oluşturulmadı.';return;}const blob=new Blob([JSON.stringify({format:FORMAT,version:1,exportedAt:new Date().toISOString(),records,courses,semester:metadata.semester,plannedSessions:metadata.plannedSessions,migrationId:migration},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='okul-yoklama-'+today+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 function invalidate(){preview=null;sourceCandidate=null;$('#attendanceApply').disabled=true;$('#attendanceImportPreview').textContent='İçerik değişti; yeniden önizle.';}
 $('#attendanceImport').addEventListener('input',invalidate);$('#attendanceMerge').addEventListener('change',invalidate);
 $('#attendancePreview').addEventListener('click',()=>{try{if(storageError)throw Error('Mevcut depolama okunamadı. Güvenli aktarım için önce mevcut veriyi kurtar.');preview=parseImport(JSON.parse($('#attendanceImport').value),courses.map(c=>c.id),today);const existing=new Map(records.map(r=>[keyOf(r),r]));const conflicts=preview.filter(r=>existing.has(keyOf(r))&&existing.get(keyOf(r)).status!==r.status),fresh=preview.filter(r=>!existing.has(keyOf(r))),same=preview.length-conflicts.length-fresh.length;$('#attendanceImportPreview').innerHTML=`<p><b>${preview.length} geçerli kayıt</b> · ${fresh.length} yeni · ${same} aynı · ${conflicts.length} çakışma</p><div class="import-preview-list">${preview.map(r=>`<div>${safe(r.courseId)} · ${safe(r.date)} · ${names[r.status]}${existing.has(keyOf(r))?' <span class="muted">(mevcut: '+names[existing.get(keyOf(r)).status]+')</span>':''}</div>`).join('')}</div><p>Çakışma davranışı: ${$('#attendanceMerge').value==='replace'?'Önizlenen durumlarla değiştirilecek.':'Mevcut kayıtlar korunacak.'} Diğer tarihler korunur.</p>`;$('#attendanceApply').disabled=preview.length===0;}catch(err){preview=null;$('#attendanceApply').disabled=true;$('#attendanceImportPreview').textContent=err instanceof SyntaxError?'JSON okunamadı. Biçimi kontrol et.':err.message;}});
 $('#attendanceApply').addEventListener('click',async()=>{if(!preview)return;if(await write(mergeRecords(records,preview,$('#attendanceMerge').value==='replace'),'Yoklama JSON’u içe aktarıldı. Son işlemi geri alabilirsin.',{importedAt:sourceCandidate?.sourceCsvSha256||migration})){preview=null;$('#attendanceApply').disabled=true;$('#attendanceImportPreview').textContent='Aktarım tamamlandı. Yoklama kayıtları bu bilgisayardaki özel dizine kaydedildi.';}});
 $('#attendanceMigrate').addEventListener('click',async()=>{try{const r=await fetch('/api/attendance/source',{cache:'no-store'});if(!r.ok)throw Error('Aktarım kaynağı okunamadı.');const source=await r.json();$('#attendanceImport').value=JSON.stringify(source,null,2);$('#attendanceMerge').value='keep';$('#attendancePreview').click();sourceCandidate=source;$('#attendanceApp .attendance-transfer').open=true;$('#attendanceImportPreview').scrollIntoView({behavior:'smooth',block:'center'});}catch(e){$('#attendanceMessage').textContent=e.message;}});
 renderSummary();renderRows();buildWeek();
}

async function undoLast(){if(!undo||busy)return;const restore=undo;if(await write(restore.records,'Son işlem geri alındı.',{importedAt:restore.migration})){undo=null;$('#attendanceUndo').disabled=true;syncWeekButtons();}}
function dateLabel(date,options){return new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',...options}).format(new Date(date+'T12:00:00+03:00'));}
function syncWeekButtons(){
 if(!$('#weekUndo'))return;$('#weekUndo').disabled=busy||!undo;$('#weekUndo').hidden=!undo;
 $('#weekPrev').disabled=busy||weekStart<=weekMonday(metadata.semester.start);
 $('#weekNext').disabled=busy||weekStart>=weekMonday(metadata.semester.end);
 $('#weekToday').disabled=busy;
 uiQueryAll('[data-session-status]').forEach(b=>b.disabled=busy||b.dataset.sessionDate>today);
}
function sessionCard(s,layout=null){
 const status=records.find(r=>keyOf(r)===keyOf(s))?.status||'unknown',feedback=sessionFeedback.get(keyOf(s));
 const clock=layout?`${clockLabel(s.start)}${s.end!==null?'–'+clockLabel(s.end):' · bitiş bilinmiyor'}`:(s.time||'Saat bilinmiyor');
 const style=layout?`style="top:${s.top}px;height:${s.height}px;left:calc(${s.lane*100/s.lanes}% + 4px);width:calc(${100/s.lanes}% - 8px)"`:'';
 return `<article class="session-card calendar-session ${layout&&s.end===null?'open-ended':''} ${status==='unknown'?'not-marked':'marked-'+status}" data-session-key="${safe(keyOf(s))}" data-start-minutes="${s.start??''}" data-end-minutes="${s.end??''}" ${style} aria-label="${safe(s.courseId+' · '+dateLabel(s.date,{day:'numeric',month:'long'})+' · '+clock)}"><div class="session-meta"><span class="course-tag">${safe(s.courseId)}</span><span class="session-date">${safe(dateLabel(s.date,{day:'numeric',month:'short'}))}</span></div><div class="calendar-class-time">${safe(clock)}</div><h4>${safe(s.title)}</h4>${s.place?`<p class="session-place" title="${safe(s.place)}">${safe(s.place)}</p>`:''}${s.note?`<details class="calendar-note"><summary>Duyuru notu${s.sourceUrl?' ↗':''}</summary><p>${safe(s.note)}</p>${s.sourceUrl?`<a class="source" href="${safe(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">Ninova duyurusu ↗</a>`:''}</details>`:''}<div class="calendar-attendance"><div class="session-buttons" role="group" aria-label="${safe(s.courseId+' '+s.date+' katılımı')}">${['attended','absent','half'].map(state=>`<button type="button" class="session-button ${state} ${status===state?'is-selected':''}" data-session-course="${safe(s.courseId)}" data-session-date="${safe(s.date)}" data-session-status="${state}" aria-pressed="${status===state}" aria-label="${safe(s.courseId+' '+dateLabel(s.date,{day:'numeric',month:'long'})+' · '+names[state])}">${names[state]}</button>`).join('')}</div><div class="session-state">${s.date>today?'Henüz gelmedi':status==='unknown'?'İşaretlenmedi':'Kaydın: '+names[status]}</div><p class="session-save ${feedback?.kind||''}" role="status">${feedback?safe(feedback.text):''}</p></div></article>`;
}
function renderAbsenceOverview(){
 if(!$('#absenceCards'))return;const num=n=>n.toLocaleString('tr-TR'),items=absenceOverview(courses,records,metadata.plannedSessions,today);
 $('#absenceCards').innerHTML=items.map(c=>`<article class="absence-card ${c.remaining!==null&&c.remaining<=1?'limit-close':''}" data-absence-course="${safe(c.courseId)}"><h4>${safe(c.courseId)}<span>${c.recordCount?'Kayıtlı':'Kayıt yok'}</span></h4><div class="absence-metric"><strong>${num(c.used)}</strong><span> / ${c.limit===null?'?':num(c.limit)}<small>kayıtlı kullanılan / kişisel limit</small></span></div><p class="absence-remaining">${c.remaining===null?'Limit bilinmiyor':c.remaining<0?'Kişisel limit aşımı: '+num(-c.remaining):'Kişisel kalan: '+num(c.remaining)}${c.remaining===null?'':' oturum'}</p><div class="absence-counts">${c.absent} katılmadım · ${c.half} yarım${c.unknown?' · '+c.unknown+' belirsiz':''}</div><a href="#attendance" data-open-panel="attendance" data-attendance-course="${safe(c.courseId)}">Kayıtları aç ↗</a></article>`).join('');
 window.keplerAttendanceOverview={items,courses,records,plannedSessions:metadata.plannedSessions||[],updatedAt:metadata.updatedAt||null,state:'ready'};document.dispatchEvent(new CustomEvent('kepler:attendance-overview',{detail:window.keplerAttendanceOverview}));
 $('#absenceSavedAt').textContent=metadata.updatedAt?'Son yerel kayıt: '+new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(metadata.updatedAt))+' İstanbul':'Yerel kayıt okundu; son kayıt saati aktarılmadı.';
}
function renderWeek(){
 renderAbsenceOverview();
 const viewport=$('#calendarScroll'),scroll={left:viewport?.scrollLeft||0,top:viewport?.scrollTop||0};
 const active=document.activeElement?.closest('[data-session-status]'),focus=active?{course:active.dataset.sessionCourse,date:active.dataset.sessionDate,status:active.dataset.sessionStatus}:null;
 const sessions=weekSessions(metadata.plannedSessions||[],weekStart,courses,schoolCourses,schoolAnnouncements).filter(s=>weekdayDates(weekStart).includes(s.date)),layout=calendarLayout(sessions),dates=weekdayDates(weekStart);
 $('#weekRange').textContent=dateLabel(weekStart,{day:'numeric',month:'long',year:'numeric'})+' – '+dateLabel(addDays(weekStart,4),{day:'numeric',month:'long',year:'numeric'});
 $('#weekDays').style.setProperty('--calendar-height',layout.height+'px');$('#weekDays').style.setProperty('--hour-height',HOUR_HEIGHT+'px');
 $('#weekDays').innerHTML=`<div class="calendar-corner">İSTANBUL</div>${dates.map(date=>`<div class="calendar-day-header ${date===today?'is-today':''}"><h3>${safe(dateLabel(date,{weekday:'long'}))}</h3><span>${safe(dateLabel(date,{day:'numeric',month:'short'}))}${date===today?' · Bugün':''}</span></div>`).join('')}<div class="calendar-time-axis">${layout.ticks.map((m,i)=>`<span class="calendar-hour ${i===0?'first-hour':''}" style="top:${(m-layout.startMinute)*HOUR_HEIGHT/60}px">${clockLabel(m)}</span>`).join('')}</div>${dates.map(date=>{const list=layout.blocks.filter(s=>s.date===date),untimed=layout.unknown.filter(s=>s.date===date);return `<section class="calendar-day-column ${date===today?'is-today':''}" aria-label="${safe(dateLabel(date,{weekday:'long',day:'numeric',month:'long'}))}" data-calendar-date="${date}">${list.map(s=>sessionCard(s,layout)).join('')}${!list.length?`<p class="calendar-no-class">${untimed.length?'Saati belirsiz kayıt var':'Kayıtlı ders yok'}</p>`:''}</section>`}).join('')}`;
 $('#calendarUnknown').innerHTML=layout.unknown.length?`<h3>Saati bilinmeyen kayıtlar</h3><p>Bu dersleri saat eksenine yerleştirmek için yeterli bilgi yok.</p><div class="calendar-unknown-items">${layout.unknown.map(s=>sessionCard(s)).join('')}</div>`:'';$('#calendarUnknown').hidden=!layout.unknown.length;
 $('#calendarEmpty').hidden=sessions.length>0;$('#weekToday').setAttribute('aria-pressed',String(weekStart===weekMonday(today)));
 if(viewport){viewport.scrollLeft=scroll.left;viewport.scrollTop=scroll.top;}
 syncWeekButtons();
 if(focus){const b=[...uiQueryAll('[data-session-status]')].find(b=>b.dataset.sessionCourse===focus.course&&b.dataset.sessionDate===focus.date&&b.dataset.sessionStatus===focus.status);b?.focus({preventScroll:true});}
}
function buildWeek(){
 $('#weekApp').innerHTML=`<details class="absence-overview"><summary class="absence-disclosure">Kişisel yoklama özetini aç</summary><div aria-labelledby="absenceTitle"><div class="absence-heading"><h3 id="absenceTitle">Derslerine göre devamsızlık</h3><span id="absenceSavedAt"></span></div><p class="absence-scope">Kendi yoklama kayıtlarından · Yarım = 0,5 oturum. Belirsiz ve işaretlenmemiş günler devamsız sayılmaz. Limitler kişisel ayarın; resmî üniversite kuralı değildir.</p><div id="absenceCards" class="absence-cards"></div></div></details><div class="week-toolbar"><div><span class="calendar-eyebrow">PAZARTESİ – CUMA · İSTANBUL</span><div class="week-range" id="weekRange"></div></div><div class="week-navigation"><button type="button" class="week-nav" id="weekPrev" aria-label="Önceki hafta">←</button><button type="button" class="week-nav" id="weekToday">Bu hafta</button><button type="button" class="week-nav" id="weekNext" aria-label="Sonraki hafta">→</button><button type="button" class="week-nav undo" id="weekUndo" disabled hidden>Geri al</button></div></div><p id="weekMessage" class="week-message" role="status" aria-live="polite"></p><div class="calendar-hint"><span>Katılımını dersin içinden işaretle. Seçili duruma tekrar dokunmak kaydı temizler.</span><div><button type="button" id="calendarLeft" aria-label="Takvim günlerini sola kaydır">←</button><span>Günleri kaydır</span><button type="button" id="calendarRight" aria-label="Takvim günlerini sağa kaydır">→</button></div></div><div class="calendar-scroll" id="calendarScroll" tabindex="0" role="region" aria-label="Yatay ve dikey kaydırılabilir haftalık ders takvimi"><div id="weekDays" class="calendar-board"></div></div><p class="calendar-empty" id="calendarEmpty" hidden>Bu haftada kaynakta kayıtlı ders oturumu yok. Yoklama kayıtların değişmedi.</p><div class="calendar-unknown" id="calendarUnknown" hidden></div><p class="calendar-end-note">Kesik alt kenar: bitiş saati bilinmiyor; kartın boyu ders süresi değildir. Saat bilgisi olmayanlar ayrı listelenir.</p><details class="week-info"><summary>Yoklama ve program hakkında</summary><p>İstanbul saati. Yoklama bu bilgisayardaki özel dizinde saklanır. İşaretlenmeyen günler devamsız sayılmaz. Haftayı değiştirmek kayıtları başka tarihe taşımaz. Program özel profilindeki tarihli oturumlardan gelir; doğrulanmış duyurular önceliklidir. Bitiş saati bilinmeyen kartın görsel yüksekliği ders süresi değildir.</p></details>`;
 $('#weekPrev').addEventListener('click',()=>{weekStart=addDays(weekStart,-7);renderWeek()});$('#weekNext').addEventListener('click',()=>{weekStart=addDays(weekStart,7);renderWeek()});$('#weekToday').addEventListener('click',()=>{const first=weekMonday(metadata.semester.start),last=weekMonday(metadata.semester.end),now=weekMonday(today);weekStart=now<first?first:now>last?last:now;renderWeek()});$('#weekUndo').addEventListener('click',undoLast);
 for(const [id,sign] of [['calendarLeft',-1],['calendarRight',1]])$("#"+id).addEventListener('click',()=>$('#calendarScroll').scrollBy({left:sign*300,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));
 $('#weekApp').addEventListener('click',async e=>{const button=e.target.closest('[data-session-status]');if(!button||busy||button.dataset.sessionDate>today)return;const courseId=button.dataset.sessionCourse,date=button.dataset.sessionDate,current=records.find(r=>r.courseId===courseId&&r.date===date)?.status||'unknown',status=button.dataset.sessionStatus===current?'unknown':button.dataset.sessionStatus,key=keyOf({courseId,date});sessionFeedback.set(key,{kind:'saving',text:'Kaydediliyor…'});renderWeek();const ok=await write(mergeRecords(records,[{courseId,date,status}],true),courseId+' · '+dateLabel(date,{day:'numeric',month:'long'})+' · '+(status==='unknown'?'İşaret temizlendi':names[status]));sessionFeedback.set(key,{kind:ok?'saved':'failed',text:ok?'Yerel dosyaya kaydedildi ✓':'Kaydedilemedi · yenileyerek kontrol et.'});renderWeek();});renderWeek();
}
document.addEventListener('click',e=>{const a=e.target.closest('[data-attendance-course]');if(a&&courses.length){selectCourse(a.dataset.attendanceCourse)}});
